import{_ as d,o as e,c as a,a2 as o}from"./chunks/framework.yO0biSGH.js";const u=JSON.parse('{"title":"27 场景决策对照：同一类业务，不同设计怎么选","description":"","frontmatter":{"title":"27 场景决策对照：同一类业务，不同设计怎么选"},"headers":[],"relativePath":"handbook/27-decisions.md","filePath":"handbook/27-decisions.md","lastUpdated":1793119197000}'),r={name:"handbook/27-decisions.md"};function h(i,t,n,l,b,s){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="_27-场景决策对照-同一类业务-不同设计怎么选" tabindex="-1">27 场景决策对照：同一类业务，不同设计怎么选 <a class="header-anchor" href="#_27-场景决策对照-同一类业务-不同设计怎么选" aria-label="Permalink to &quot;27 场景决策对照：同一类业务，不同设计怎么选&quot;">​</a></h1><blockquote><p>详细程度：速查 · 约 20 分钟 材料：W03-1、W04-2、W04-6、W06-2、W09-1、W10-3、W11-1、W12-2、W13-2、W14-1、W15-2、W16-2、W17-2、W19-1、W19-2、WX-sms · 旧长版：无 前置：先读过对应正文章节，本节只做横向对照 说明：本节是决策索引，不是教程。每个场景给方案对照、判据和手册落点；展开与可运行示例在各节。</p></blockquote><h2 id="先看一个让人犹豫的时刻" tabindex="-1">先看一个让人犹豫的时刻 <a class="header-anchor" href="#先看一个让人犹豫的时刻" aria-label="Permalink to &quot;先看一个让人犹豫的时刻&quot;">​</a></h2><p>评审会上被问&quot;计数为什么不用 Redis 直接存？&quot;、登录为什么选 JWT 不选 Session、&quot;这个表为什么要拆两张&quot;。这些问题的答案散在各节正文里，临场容易想不全。这一节把它们收成一张对照表：每个业务场景，课程里出现过的方案、各自的代价、怎么定。它不替代正文，替你省的是&quot;我记得讲过，在哪一节来着&quot;。〔W21-1 p3〕</p><h2 id="一、登录态与凭证" tabindex="-1">一、登录态与凭证 <a class="header-anchor" href="#一、登录态与凭证" aria-label="Permalink to &quot;一、登录态与凭证&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>适合</th><th>代价</th></tr></thead><tbody><tr><td>Session（服务端存储）</td><td>单体或少量服务，需要立刻登出</td><td>状态在服务端，扩容要共享存储</td></tr><tr><td>JWT（无状态签名）</td><td>无状态服务、跨服务鉴权</td><td>登出难，签出后到过期前一直有效</td></tr><tr><td>长短 token</td><td>上述两者折中</td><td>refresh 轮换逻辑要自己做</td></tr></tbody></table><p>判据：<strong>先问登出要不要立刻生效</strong>。要立刻登出且有集中存储，Session；要无状态水平扩容，JWT 加黑名单或短过期；移动端长会话，长短 token（access 短、高频、易泄露；refresh 长且只用于刷新，泄露面小）。第三方登录跳 OAuth2，微信扫码就是授权码流程的特例。〔W03-1 p5〕〔W05-2 p5-7〕〔W05-1 p4-12〕验证码登录的竞态处理（lua 原子化）见 11 节。 实战落点：<code>minifeed/auth</code> 的 <code>SignToken</code>/<code>ParseToken</code> 就是无状态签名的最小 Go 版（HMAC 加过期校验，80 行）；给登录态补&quot;立刻登出&quot;，思路是给 token 加版本号并把版本存服务端，校验时多比一次。</p><h2 id="二、计数与关系数据" tabindex="-1">二、计数与关系数据 <a class="header-anchor" href="#二、计数与关系数据" aria-label="Permalink to &quot;二、计数与关系数据&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>适合</th><th>代价</th></tr></thead><tbody><tr><td>维护计数列（事务更新）</td><td>计数要与关系数据一致、参与业务判断</td><td>热点行竞争；需用原子更新或事务约束并发</td></tr><tr><td>Redis 计数 + Count 兜底</td><td>弱一致可接受、读多写多</td><td>缓存 miss 时 Count 慢，快慢路径要降级设计</td></tr><tr><td>不缓存</td><td>低频读</td><td>大 V 的高频读打穿数据库</td></tr></tbody></table><p>判据：<strong>先问这个计数差一个能不能接受</strong>。粉丝数差 1 无感就走 Redis 加兜底；库存、余额差 1 是事故就维护计数列加事务。&quot;是否关注某人&quot;只在大 V 场景值得缓存，小透明之间命中率太低。〔W16-2 p14〕〔W16-2 p15〕〔W16-2 p13〕 实战落点：<code>minifeed/counter</code> 的 <code>MemoryCounter</code> 是&quot;内存计数加批量落库&quot;的 Go 版：<code>Like</code>/<code>Unlike</code> 改内存 map，<code>flush</code> 回调定期落库，落库失败只记日志不堵主路径。把 flush 换成写 Redis、再加 Count 兜底，就是课程方案的完整形态。</p><h2 id="三、内容状态与存储选型" tabindex="-1">三、内容状态与存储选型 <a class="header-anchor" href="#三、内容状态与存储选型" aria-label="Permalink to &quot;三、内容状态与存储选型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>适合</th><th>代价</th></tr></thead><tbody><tr><td>单库单表加状态列</td><td>状态少、读路径单一</td><td>线上查询要带 status 过滤</td></tr><tr><td>制作库/线上库分库</td><td>创作侧草稿与读者侧可见性分离</td><td>跨库操作没有事务，要自己设计补偿</td></tr><tr><td>内容正文挪 OSS + CDN</td><td>正文大、图片多媒体多</td><td>CDN 缓存失效是漏洞（仅自己可见时对象删了缓存还在）</td></tr></tbody></table><p>判据：<strong>先问读者侧和创作侧的读模式差多少</strong>。差得多就分库；正文只是文本先不分。零值禁忌恒成立：<code>Unknown=0</code> 不许做成有意义的业务状态。换存储（MySQL 到 MongoDB）是 DAO 层的事，上层不动；没有自增主键就雪花算法。〔W06-2 p13〕〔W06-2 p48-52〕〔W06-2 p32-33〕 实战落点：<code>minifeed/post</code> 与 <code>minifeed/user</code> 各有 <code>MemoryStore</code>/<code>SQLiteStore</code> 双实现，同一接口两种存储，Service 层零改动，这就是&quot;换存储是 DAO 层的事&quot;的可运行证明。</p><h2 id="四、消息幂等与去重" tabindex="-1">四、消息幂等与去重 <a class="header-anchor" href="#四、消息幂等与去重" aria-label="Permalink to &quot;四、消息幂等与去重&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>适合</th><th>代价</th></tr></thead><tbody><tr><td>唯一索引（biz_type+biz_id）</td><td>所有能补业务键的场景</td><td>键设计错了要改表</td></tr><tr><td>状态机（只允许合法迁移）</td><td>流程型业务（订单、支付）</td><td>状态枚举要维护</td></tr><tr><td>乐观锁（版本号条件更新）</td><td>更新冲突低频</td><td>高冲突下重试率高</td></tr></tbody></table><p>判据：<strong>先问重复执行一次会怎样</strong>。天然幂等（设置为某值）可能无需额外去重；其他操作可以用业务唯一键，但去重记录与业务变更须有一致的提交边界，重复请求如何返回也要定义。短信服务的幂等回放进一步查上次结果返回。〔W09-2 p20〕〔WX-sms p3〕 实战落点：<code>minifeed/user</code> 的 SQLite 建表里 <code>email TEXT UNIQUE</code>，<code>Create</code> 把唯一约束冲突当业务分支处理。它保证邮箱不重复，但重复创建返回冲突并不等于幂等回放；要做到回放，还需要请求身份和结果记录。</p><h2 id="五、缓存一致性" tabindex="-1">五、缓存一致性 <a class="header-anchor" href="#五、缓存一致性" aria-label="Permalink to &quot;五、缓存一致性&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>适合</th><th>代价</th></tr></thead><tbody><tr><td>先更新库再删缓存</td><td>大多数读写场景</td><td>删除失败要重试兜底</td></tr><tr><td>订阅 binlog 异步删（Canal）</td><td>要解耦、删失败率要低</td><td>多一套 Canal 组件与延迟</td></tr><tr><td>双写</td><td>读极敏感</td><td>并发下不一致窗口难消灭</td></tr></tbody></table><p>判据：<strong>先问能不能容忍短暂不一致，以及能容忍多久</strong>。异步订阅会引入投递延迟；同步删加重试也有并发读回填旧值和删除失败的窗口，不能单凭它保证强一致。需要强一致时，应重新设计读写协议及故障处理，而不只是切换删缓存方式。〔W13-2 p3-5〕</p><h2 id="六、跨服务事务" tabindex="-1">六、跨服务事务 <a class="header-anchor" href="#六、跨服务事务" aria-label="Permalink to &quot;六、跨服务事务&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>适合</th><th>代价</th></tr></thead><tbody><tr><td>二阶段消息</td><td>不需要回滚，下游必然成功</td><td>只覆盖&quot;发出去必到达&quot;，不含逆操作</td></tr><tr><td>SAGA</td><td>长事务拆短事务，失败逆序补偿</td><td>每步要写补偿，中间状态对外可见</td></tr><tr><td>TCC</td><td>一致性要求高，不接受&quot;先改后补偿&quot;</td><td>Try/Confirm/Cancel 三套接口，侵入业务</td></tr><tr><td>XA</td><td>并发不高、无热点争抢</td><td>prepare 期间持锁，性能差</td></tr></tbody></table><p>判据（DTM 口诀）：<strong>先问失败时要不要回滚</strong>。不需要回滚（发消息、发短信、删缓存）用二阶段消息；要回滚（下单涉及建单、扣库存、扣券多步）用 SAGA；&quot;先改后补偿&quot;不可接受才上 TCC；并发不高且有数据库原生支持才考虑 XA。秒杀是二阶段消息的典型：Prepare 在 Redis 扣库存（大概率失败），Commit 才写 MySQL 订单。〔C:dachang/distributed_transaction/分布式事务模式.md:54-59〕自建形态是 outbox 本地消息表（业务数据与待发消息同事务写入，中继异步投递），与消费端幂等是同一枚硬币的两面，展开见 18 节。〔W15-2 p12-14〕</p><h2 id="七、数据迁移" tabindex="-1">七、数据迁移 <a class="header-anchor" href="#七、数据迁移" aria-label="Permalink to &quot;七、数据迁移&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>适合</th><th>代价</th></tr></thead><tbody><tr><td>停机迁移</td><td>中小体量、可停窗口</td><td>停机时长随数据量线性涨</td></tr><tr><td>双写迁移（八步）</td><td>不许停机</td><td>步骤多，校验任务要跑很久</td></tr></tbody></table><p>判据：<strong>先问数据在迁移期间会不会变</strong>。不会变（一次导入的归档表）就停机直搬；会变就得面对&quot;蜗牛悖论&quot;：校平了旧库，应用一写新库又落后，只能双写加增量校验追平，最后切读、切单写。〔W11-1 p6〕〔W11-1 p9〕〔W11-1 p11〕</p><h2 id="八、feed-流生成" tabindex="-1">八、Feed 流生成 <a class="header-anchor" href="#八、feed-流生成" aria-label="Permalink to &quot;八、Feed 流生成&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>适合</th><th>代价</th></tr></thead><tbody><tr><td>推（写扩散进收件箱）</td><td>粉丝数低于阈值的普通作者</td><td>大 V 发文写放大：百万粉一次发文百万条记录</td></tr><tr><td>拉（读扩散查发件箱）</td><td>大 V、粉丝量不可控的账号</td><td>读放大：每次读合并 N 路查询，分页要各路取前 20 再内存排序</td></tr><tr><td>推拉结合</td><td>生产环境的标准答案</td><td>两套路径都要实现，阈值要压测定</td></tr></tbody></table><p>判据：<strong>先问作者粉丝数的分布</strong>。全体都是小透明，纯推就够；有几个头部大 V，纯推必然写放大、纯拉必然读放大，按粉丝阈值分流：低于阈值走推，超过走拉，再叠加&quot;只对活跃用户推&quot;。口诀：读扩散查询慢，写扩散数据多；推拉结合不消灭缺陷，只是让两个都变轻。〔W19-1 p9-19〕</p><p>实战落点：25 节提出的 <code>FeedStore</code> 接口蓝图同时有 Inbox（推）与 Outbox（拉）两套；阈值怎么定见 21 节压测段。</p><h2 id="九、榜单与热门计算" tabindex="-1">九、榜单与热门计算 <a class="header-anchor" href="#九、榜单与热门计算" aria-label="Permalink to &quot;九、榜单与热门计算&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>适合</th><th>代价</th></tr></thead><tbody><tr><td>异步定时全量计算</td><td>榜单更新间隔分钟级即可</td><td>实时性差，计算窗口内新数据不体现</td></tr><tr><td>流式增量更新</td><td>实时性要求高</td><td>实现复杂，要处理乱序与回撤</td></tr></tbody></table><p>判据：<strong>先问榜单的实时性是产品需求还是研发执念</strong>。课程选 HackerNews 模型（投票数加时间衰减）加定时计算，千万级数据实时算谁都扛不住，间隔可控的异步计算加缓存才是正解。〔W09-1 p4〕〔W09-1 p12〕〔W09-1 p13〕 实战落点：<code>minifeed/rank</code> 的 <code>Refresh</code>（13 行）：TTL 内直接返回旧榜（幂等），并发刷新用 mutex 单飞，真算失败沿用旧榜，&quot;定时全量加宁可旧不可挂&quot;的最小样本。</p><h2 id="十、服务间调用与负载均衡" tabindex="-1">十、服务间调用与负载均衡 <a class="header-anchor" href="#十、服务间调用与负载均衡" aria-label="Permalink to &quot;十、服务间调用与负载均衡&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>适合</th><th>代价</th></tr></thead><tbody><tr><td>客户端轮询（roundrobin）</td><td>节点性能均匀</td><td>不感知负载</td></tr><tr><td>平滑 WRR（自算权重）</td><td>节点性能不均或要按错误率避让</td><td>客户端要维护权重状态</td></tr><tr><td>集中式 LB（grpclb/独立代理）</td><td>统一管控</td><td>多一跳延迟与组件运维</td></tr></tbody></table><p>判据：<strong>先问要不要为省一次转发付复杂度</strong>。gRPC 默认 pick_first（永远选第一个节点），多副本部署必须显式配负载均衡；官方 WRR 是客户端按 QPS 与错误率自算权重加 EDF 挑选，不依赖服务端配置权重。注册中心选型要问四件事：自动续约有没有、续约失败怎么处理、变更多久同步到客户端、SDK 是否可换。〔W13-2 p4〕〔W13-2 p9〕〔W12-2 p19〕</p><h2 id="十一、限流与容错阀门" tabindex="-1">十一、限流与容错阀门 <a class="header-anchor" href="#十一、限流与容错阀门" aria-label="Permalink to &quot;十一、限流与容错阀门&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>适合</th><th>代价</th></tr></thead><tbody><tr><td>并发计数器</td><td>限&quot;同时在处理多少个&quot;，保护自身资源</td><td>不限速率，慢请求占坑时间长</td></tr><tr><td>令牌桶</td><td>限速率且要放行合理突发</td><td>参数（速率、容量）要靠压测定</td></tr><tr><td>漏桶</td><td>要绝对匀速 outbound（如调第三方）</td><td>攒的突发全被削平</td></tr></tbody></table><p>容错侧的对立选择：熔断（下游持续失败就整段拒绝，给它喘息）对 failover（换节点再试，节点级故障）对舱壁（每个下游独立并发池，一个下游挂了不拖垮别的）。判据：<strong>先问故障是速率问题还是节点问题</strong>。下游整体过载，failover 只是换一个一样过载的节点，该熔断；单节点故障，熔断把好节点也拒了，该 failover；多个互不相关的下游，舱壁做隔离。三者常叠加：入口限流、下游熔断加 failover、关键路径舱壁。〔W14-1 p20〕〔W14-1 p25〕〔W14-1 p13〕〔W04-6 p25-26〕</p><p>实战落点：<code>dnsproxi-go/guard</code> 是两个阀门的最小 Go 版：<code>TokenBucket.Allow</code>/<code>WaitN</code>（时钟注入，测试不用真等待，111 行）、<code>Breaker</code> 三态加环形失败窗口（189 行）；16 节正文有逐行讲解与 <code>golang.org/x/time/rate</code>、<code>sony/gobreaker</code> 的生产选型。</p><h2 id="十二、支付类异步结果" tabindex="-1">十二、支付类异步结果 <a class="header-anchor" href="#十二、支付类异步结果" aria-label="Permalink to &quot;十二、支付类异步结果&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>适合</th><th>代价</th></tr></thead><tbody><tr><td>回调（服务商通知你）</td><td>一切能收回调的场景</td><td>回调会丢会迟到，要有补偿</td></tr><tr><td>前端轮询</td><td>用户在支付页等结果的场景</td><td>轮询频率与超时次数要设计</td></tr></tbody></table><p>判据：<strong>回调与查询可以互补，但前端轮询自己的服务不能凭空获知支付结果</strong>。服务收到并验证回调后更新订单状态，前端轮询该状态以展示结果；若回调迟迟未到，服务端还应按支付服务商接口主动查单并幂等更新状态。超时不等于支付失败，应保留待确认状态并继续对账或补偿。〔W15-2 p10〕</p><h2 id="十三、搜索接入" tabindex="-1">十三、搜索接入 <a class="header-anchor" href="#十三、搜索接入" aria-label="Permalink to &quot;十三、搜索接入&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>适合</th><th>代价</th></tr></thead><tbody><tr><td>数据库 LIKE</td><td>数据量小、场景内部</td><td>全表扫，不可控</td></tr><tr><td>同步双写到 ES</td><td>一致性要求高</td><td>写路径变长，失败要补偿</td></tr><tr><td>binlog 订阅到 ES</td><td>解耦、允许秒级延迟</td><td>多一套组件</td></tr></tbody></table><p>判据：<strong>先问搜索是不是核心写路径</strong>。站内搜索几乎都不是，binlog 订阅最常见。字段设计先过隐私：email/phone 公开平台不可搜，toB 私有 IM 才要可搜。〔W17-2 p6〕〔W17-2 p13〕</p><h2 id="十四、压测工具" tabindex="-1">十四、压测工具 <a class="header-anchor" href="#十四、压测工具" aria-label="Permalink to &quot;十四、压测工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>适合</th><th>代价</th></tr></thead><tbody><tr><td>wrk</td><td>冒烟、单接口吞吐</td><td>脚本能力弱</td></tr><tr><td>k6 + Prometheus + Grafana</td><td>正式压测、要图表与指标留存</td><td>全栈搭建</td></tr></tbody></table><p>判据：<strong>wrk 做冒烟，k6 做正餐</strong>。读要分 push/pull/混合三维度、数据量分档压，推拉阈值才有依据；延迟分解排查表（blocked/sending/receiving 谁非零）比总 P99 有用。〔W19-2 p4〕〔W19-2 p12〕</p><h2 id="十五、微服务框架" tabindex="-1">十五、微服务框架 <a class="header-anchor" href="#十五、微服务框架" aria-label="Permalink to &quot;十五、微服务框架&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>适合</th><th>代价</th></tr></thead><tbody><tr><td>标准库 + gRPC</td><td>团队小、需求可控</td><td>生态件自己拼</td></tr><tr><td>go-zero</td><td>要一站式（Web+RPC+治理）</td><td>框架绑定，底层仍是 gRPC</td></tr><tr><td>Dubbo-go</td><td>要与 Java 侧 Dubbo 互通</td><td>社区相对小</td></tr></tbody></table><p>判据：<strong>功能性、成熟度、非功能性三维度打分</strong>（业务无特别则主流都够；看社区与招人；性能中小公司基本不用管），别为 benchmark 1% 的差距选小众框架。API 管理三方案（公司级仓库/服务内目录/API 与实现分离）按团队规模选，30 人内公司级仓库最省心。〔W10-3 p4〕〔W10-3 p7〕</p><h2 id="怎么用这一节" tabindex="-1">怎么用这一节 <a class="header-anchor" href="#怎么用这一节" aria-label="Permalink to &quot;怎么用这一节&quot;">​</a></h2><ol><li>评审被问&quot;为什么不用 X&quot;时，先定位场景，再按判据句作答；判据都在&quot;先问&quot;后面。</li><li>每张表都是课程里真实出现过的方案，不是穷举；你的场景若三个方案都不匹配，回对应章节看约束再决定。</li><li>判据冲突时（既要强一致又要高并发写），回到 18 节一致性那一章：先定业务能接受哪头弱。</li></ol><h2 id="想深入去哪查" tabindex="-1">想深入去哪查 <a class="header-anchor" href="#想深入去哪查" aria-label="Permalink to &quot;想深入去哪查&quot;">​</a></h2><ul><li>登录与凭证：11 节认证小节；原材料 W03-1、W05-1、W05-2。</li><li>计数与关系：21 节用户关系段；原材料 W16-2。</li><li>状态与存储：12 节内容状态机段；原材料 W06-2。</li><li>迁移：17 节；原材料 W11-1、W11-2。</li><li>负载均衡：19 节；原材料 W13-1、W13-2。</li><li>压测：21 节压测段；原材料 W19-2。</li><li>Feed 与事务：21 节 Feed 段、18 节；原材料 W19-1、W15-2。</li></ul>',55)])])}const p=d(r,[["render",h]]);export{u as __pageData,p as default};
